import os
tot=0
for root,dirs,files in os.walk('.'):
    if '.git' in dirs: dirs.remove('.git')
    for f in files:
        p=os.path.join(root,f)
        try: t=open(p,errors='replace').read()
        except: continue
        c=t.count('TODO')
        if c: print(p,c); tot+=c
print('total',tot)

import os
allf=[]; bad=[]
for root,dirs,files in os.walk('.'):
    for f in files:
        p=os.path.join(root,f); allf.append(p)
        try: open(p,'rb').read()
        except Exception as e: bad.append((p,str(e)))
print(len(allf), bad)
print([p for p in allf if '.git' in p][:5])

for p in allf:
